import{_ as s,c as a,b as e,o as t}from"./app-90veb4I1.js";const p={};function o(c,n){return t(),a("div",null,n[0]||(n[0]=[e(`<h1 id="logic" tabindex="-1"><a class="header-anchor" href="#logic"><span>Logic</span></a></h1><p>To check for specific conditions in your data, Openmadness makes it easy to compare numbers within your arrays. These operations create a new Openmadness array where each value is true or false (also known as a boolean).</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> om <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> sensorReadings <span class="token operator">=</span> om<span class="token punctuation">.</span><span class="token function">array</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">15</span><span class="token punctuation">,</span> <span class="token number">22</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">,</span> <span class="token number">28</span><span class="token punctuation">,</span> <span class="token number">19</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Sensor Readings:&quot;</span><span class="token punctuation">,</span> sensorReadings<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Is each reading greater than 20?</span></span>
<span class="line"><span class="token keyword">const</span> aboveThreshold <span class="token operator">=</span> sensorReadings<span class="token punctuation">.</span><span class="token function">greaterThan</span><span class="token punctuation">(</span><span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Readings &gt; 20:&quot;</span><span class="token punctuation">,</span> aboveThreshold<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [false, true, false, true, false, true]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Is each reading less than or equal to 15?</span></span>
<span class="line"><span class="token keyword">const</span> belowOrEqual <span class="token operator">=</span> sensorReadings<span class="token punctuation">.</span><span class="token function">lessThanOrEqual</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Readings &lt;= 15:&quot;</span><span class="token punctuation">,</span> belowOrEqual<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [true, false, true, false, false, false]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Is any reading exactly 30?</span></span>
<span class="line"><span class="token keyword">const</span> isThirty <span class="token operator">=</span> sensorReadings<span class="token punctuation">.</span><span class="token function">equal</span><span class="token punctuation">(</span><span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Readings == 30:&quot;</span><span class="token punctuation">,</span> isThirty<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [false, false, false, false, false, true]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Is any reading NOT equal to 19?</span></span>
<span class="line"><span class="token keyword">const</span> notNineteen <span class="token operator">=</span> sensorReadings<span class="token punctuation">.</span><span class="token function">notEqual</span><span class="token punctuation">(</span><span class="token number">19</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Readings != 19:&quot;</span><span class="token punctuation">,</span> notNineteen<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [true, true, true, true, false, true]</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,3)]))}const i=s(p,[["render",o]]),u=JSON.parse('{"path":"/tutorials/fundamentals/logic.html","title":"Logic","lang":"en-US","frontmatter":{"title":"Logic","description":"This page will guide you on how to install openmadness"},"headers":[],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"tutorials/fundamentals/logic.md"}');export{i as comp,u as data};
